"""A simple log mechanism styled after PEP 282."""

# The class here is styled after PEP 282 so that it could later be
# replaced with a standard Python logging implementation.

import sys

DEBUG = 1
INFO = 2
WARN = 3
ERROR = 4
FATAL = 5


class Log:
    """类 Log：封装与该模块相关的数据与行为。"""
    def __init__(self, threshold=WARN):
        """函数 __init__：处理 threshold 相关逻辑。"""
        self.threshold = threshold

    def _log(self, level, msg, args):
        """函数 _log：处理 level, msg, args 相关逻辑。"""
        if level not in (DEBUG, INFO, WARN, ERROR, FATAL):
            raise ValueError('%s wrong log level' % str(level))

        if level >= self.threshold:
            if args:
                msg = msg % args
            if level in (WARN, ERROR, FATAL):
                stream = sys.stderr
            else:
                stream = sys.stdout
            try:
                stream.write('%s\n' % msg)
            except UnicodeEncodeError:
                # emulate backslashreplace error handler
                encoding = stream.encoding
                msg = msg.encode(encoding, "backslashreplace").decode(encoding)
                stream.write('%s\n' % msg)
            stream.flush()

    def log(self, level, msg, *args):
        """函数 log：处理 level, msg, *args 相关逻辑。"""
        self._log(level, msg, args)

    def debug(self, msg, *args):
        """函数 debug：处理 msg, *args 相关逻辑。"""
        self._log(DEBUG, msg, args)

    def info(self, msg, *args):
        """函数 info：处理 msg, *args 相关逻辑。"""
        self._log(INFO, msg, args)

    def warn(self, msg, *args):
        """函数 warn：处理 msg, *args 相关逻辑。"""
        self._log(WARN, msg, args)

    def error(self, msg, *args):
        """函数 error：处理 msg, *args 相关逻辑。"""
        self._log(ERROR, msg, args)

    def fatal(self, msg, *args):
        """函数 fatal：处理 msg, *args 相关逻辑。"""
        self._log(FATAL, msg, args)


_global_log = Log()
log = _global_log.log
debug = _global_log.debug
info = _global_log.info
warn = _global_log.warn
error = _global_log.error
fatal = _global_log.fatal


def set_threshold(level):
    """函数 set_threshold：处理 level 相关逻辑。"""
    # return the old threshold for use from tests
    old = _global_log.threshold
    _global_log.threshold = level
    return old


def set_verbosity(v):
    """函数 set_verbosity：处理 v 相关逻辑。"""
    if v <= 0:
        set_threshold(WARN)
    elif v == 1:
        set_threshold(INFO)
    elif v >= 2:
        set_threshold(DEBUG)
